/* ---------- document builder (founder console) ---------- */
const TPL_BUILTIN=[{"id": "address", "name": "Business address use agreement (Jaipur flat)", "title": "Business Address Use and Authorisation Agreement", "titleHi": "व्यावसायिक पता उपयोग और अनुमति एग्रीमेंट", "subtitle": "Official business address for website, Google listing, letters and client meetings · Haritt Developers, a Haritt Group venture", "subtitleHi": "वेबसाइट, Google listing, चिट्ठियों और ग्राहक मीटिंग के लिए official business address · Haritt Developers, Haritt Group की एक venture", "md": "Date: **{{date}}**     Place: **{{owner_place}}**\n## Who is making this agreement\n- **Owner:** {{owner_name}}, {{owner_parent}}, living at {{owner_addr}}. Mobile: {{owner_mobile}}. Email: {{owner_email}}. (“Owner”)\n- **Haritt Developers:** a venture of **Haritt Group**. It is a business that is not yet registered. Its main working address is Behind Shiva Talkies, Sahyog Nagar, Bharatpur, Rajasthan 321001. Email: developers@haritt.com. It is run by its founders **{{f1_name}}** and **{{f2_name}}**. (“Haritt”)\n## The flat\nThe Owner owns this flat: **{{owner_flat_addr}}**. (“Flat”)\n## Purpose of this agreement\nThe main purpose of this agreement is simple. The Owner gives Haritt Developers the **right to officially use the address of the Flat as its business address** on its **website, Google Business Profile, other online listings, social media profiles, emails, bills, quotations, contracts and every other place where Haritt shows its business details**. Haritt will use it openly and officially, and the Owner is fully aware of this and agrees.\n# What the Owner allows\n- Haritt can use the address of the Flat as its **mailing (correspondence) address** on its website, emails, bills, quotes and contracts, and as its **Jaipur address for correspondence and client meetings**.\n- Haritt can receive letters and courier at the Flat.\n- Haritt can say on its website and profiles: **“Jaipur address (correspondence and meetings): {{owner_flat_addr}}. Client meetings by prior appointment only.”** It can also say it **serves clients in Jaipur and Rajasthan**.\n- Haritt can hold **a few meetings** at the Flat, with its clients and business partners, only when the Owner agrees in advance (see point 3).\n- **Google Business Profile.** Haritt can create and manage a Google Business Profile (and similar listings) for this address, showing it as an address for **appointment-only meetings**. If Google asks for proof such as a postcard, code or phone call, the Owner will help in a reasonable way. He does not have to show private parts of his home.\n# What Haritt will not do\n- It will **not** say the Flat has staff, open hours, or a shop or showroom. It will not call it a branch, head office or registered office. It will always say meetings are **by appointment only**.\n- It will **not** keep staff, stock, equipment or files at the Flat. It will not put up any board or sign. There will be no walk-in visitors, events, sales or cash dealings.\n- It will **not** use this address for GST, Udyam, company registration, or bank or payment account forms. If this is needed later, the Owner must agree separately in writing.\n- It will not put the Owner’s name, photo or personal details on the website or anywhere public. It will not upload photos of the Flat’s inside.\n- Haritt will follow Google’s rules for its listing. If Google suspends or removes the listing, that is Haritt’s problem only. If the listing causes trouble (for example people coming without appointment, or a society complaint), the Owner can ask Haritt to remove it with **15 days’ notice** and Haritt will do so within 7 days. The other permissions continue.\n- Other Haritt Group ventures will not use this address unless the Owner agrees in writing (see 9.2).\n# Meetings at the Flat\n- Haritt will ask in advance by WhatsApp or email, **at least 2 days before**. It will say the date, time, purpose and names of people coming.\n- The Owner will reply within 1 day. The Owner can say no only for a fair reason, such as: he is not free, family or health reason, repair work, society rule, safety, or a visitor not told in advance. He will give the reason and offer another day within 7 days.\n- Limits: up to **4 meetings a month** (can be increased by a written message from the Owner), each up to **2 hours**, between **10 am and 6 pm**, with up to **4 people**.\n- Haritt’s clients and business partners can come, but only if their names are told in advance, and a founder must come with them. Haritt is responsible for how its visitors behave, and will follow society rules.\n# Letters and courier\n- The Owner will keep Haritt’s letters and parcels safely when he is at home. He can refuse cash-on-delivery, valuable, heavy or suspicious items.\n- If a government, tax, bank or court letter comes, the Owner will tell Haritt **within 2 working days** and will not open it. Haritt will collect it within 7 days.\n- The Owner is not responsible if a letter is lost, unless he was very careless. He is not Haritt’s agent for receiving legal notices.\n- Haritt pays all courier and return costs.\n# What this agreement is not\n- It is **not** a rent agreement, lease or tenancy. Haritt gets **no right to live in, hold or own** any part of the Flat. The Owner keeps full control and can sell or rent the Flat.\n- It does not make the Owner a partner, employer or guarantor of Haritt. The Owner is **not responsible** for Haritt’s business, debts, taxes or contracts.\n- **No money** is to be paid by either side. Haritt pays its own costs. The Owner pays the Flat’s society, tax and electricity bills as usual. If money is ever agreed, it must be written and signed by both.\n# Responsibility\n- Haritt is responsible for its business, its mail contents, and its visitors. If Haritt or its visitors damage anything in the Flat, Haritt will pay for it. If anyone makes a claim against the Owner because of Haritt’s business or this address, Haritt will handle it and cover the cost, unless it was caused by the Owner’s own fault.\n- The Owner promises that: he is the owner (or all owners agree); no bank, landlord or builder rule stops this; and he has checked that his society does not forbid receiving letters, occasional client meetings and a Google listing for this address. If this is untrue and Haritt has to change its records, the Owner will pay the reasonable cost up to ₹{{cap}}.\n- The Owner will tell Haritt **within 7 days** if his society, a rule, a notice, a sale, a mortgage or a plan to leave the Flat can affect this agreement. If a rule or order makes one thing not allowed, only that thing stops. The rest continues.\n# Privacy\n- Each side will keep the other’s private information private. Haritt will keep copies of the Owner’s ID safe, use them only for this agreement, and delete them within 30 days after it ends. The Owner will not open Haritt’s mail unless it is needed for safety or law.\n# How long it lasts and how to end it\n- It starts on the date above and runs for **12 months**. It then continues each year unless someone gives 30 days’ notice not to continue.\n- In the first 12 months, **Haritt** can end it at any time with **15 days’ notice**. The **Owner** can end it only for these reasons: Haritt breaks this agreement and does not fix it within 7 days; a society or legal rule makes it not possible; the Flat is sold or he must leave it; Haritt closes its business; or the Owner dies or cannot act (his family can then end it with 30 days’ notice).\n- After 12 months, either side can end it for any reason with **30 days’ written notice**. WhatsApp or email is fine.\n- During the notice period everything stays as agreed. Meetings already confirmed stay unless there is an emergency.\n- Within the notice period Haritt will remove the address from its website, **Google listing**, profiles and papers, and tell the Owner in writing. The Owner will keep accepting letters for **60 days after the end date**, then may return them to the sender.\n- If the Owner asks, or Haritt asks, the Owner will give a short letter confirming that Haritt used the address with his permission during this period.\n# Keeping a clear record\n- Only this agreement and later written messages (WhatsApp or email from the numbers below) count as permission. Spoken promises do not count.\n- What is written in this agreement cannot be denied later by either side. Any new permission must be written, for example: “Yes, you can do this on this date.”\n- Contact for messages. Owner: {{owner_mobile}}, {{owner_email}}. Haritt: developers@haritt.com, {{haritt_mobile}}.\n# Problems\n- If there is a disagreement, first talk within 7 days and try to fix it in 15 days. If not fixed, try a neutral mediator. If still not fixed, the courts in Jaipur, Rajasthan will decide. Indian law applies.\n# Other points\n- Haritt is not registered, so the **founders also sign personally** and are responsible for Haritt’s promises here. If Haritt registers later, it will tell the Owner within 15 days and both will sign a short note moving this agreement to the registered business.\n- Neither side can pass this agreement to anyone else. Changes must be written and signed by both, except new permissions under 9.2.\n- This is the full agreement on this subject. Both sides have read it, understood it, and sign by free choice. Haritt pays the stamp paper cost.", "hi": ["तारीख: **{{date}}**     स्थान: **{{owner_place}}**", "यह एग्रीमेंट कौन कर रहा है", "**मालिक:** {{owner_name}}, {{owner_parent}}, निवासी {{owner_addr}}. मोबाइल: {{owner_mobile}}. ईमेल: {{owner_email}}. (“मालिक”)", "**Haritt Developers:** **Haritt Group** की एक venture. यह एक ऐसा बिज़नेस है जो अभी रजिस्टर्ड नहीं है. इसका मुख्य काम का पता है: Behind Shiva Talkies, Sahyog Nagar, Bharatpur, Rajasthan 321001. ईमेल: developers@haritt.com. इसे इसके founders **{{f1_name}}** और **{{f2_name}}** चलाते हैं. (“Haritt”)", "फ्लैट", "मालिक इस फ्लैट का मालिक है: **{{owner_flat_addr}}**. (“फ्लैट”)", "इस एग्रीमेंट का मकसद", "इस एग्रीमेंट का मुख्य मकसद सीधा है. मालिक Haritt Developers को फ्लैट के पते को **अपने business address की तरह officially इस्तेमाल करने का अधिकार** देता है. यह अधिकार **वेबसाइट, Google Business Profile, दूसरी online listings, social media profiles, ईमेल, बिल, quotation, contract और हर उस जगह** के लिए है जहाँ Haritt अपनी business जानकारी दिखाता है. Haritt इसे खुले तौर पर और officially इस्तेमाल करेगा, और मालिक को यह पूरी तरह पता है और वह इससे सहमत है.", "1. मालिक क्या इजाज़त देता है", "Haritt फ्लैट के पते को अपनी वेबसाइट, ईमेल, बिल, quotation और contract पर **मेलिंग (पत्राचार) पते** के रूप में, और **जयपुर में पत्राचार व ग्राहकों से मीटिंग के पते** के रूप में इस्तेमाल कर सकता है.", "Haritt फ्लैट पर चिट्ठियाँ और courier ले सकता है.", "Haritt अपनी वेबसाइट और profiles पर यह लिख सकता है: **“जयपुर का पता (पत्राचार और मीटिंग): {{owner_flat_addr}}. ग्राहक मीटिंग सिर्फ़ पहले से appointment लेकर.”** वह यह भी लिख सकता है कि वह **जयपुर और राजस्थान में ग्राहकों की सेवा करता है**.", "Haritt अपने ग्राहकों और business partners के साथ फ्लैट पर **कुछ मीटिंग** कर सकता है, लेकिन सिर्फ़ तब जब मालिक पहले से हाँ कहे (बिंदु 3 देखें).", "**Google Business Profile.** Haritt इस पते के लिए Google Business Profile (और ऐसी ही listings) बना और चला सकता है, जिसमें इसे **सिर्फ़ appointment वाली मीटिंग** के पते के रूप में दिखाया जाएगा. अगर Google कोई सबूत माँगे, जैसे postcard, code या phone call, तो मालिक ठीक तरह से मदद करेगा. उसे अपने घर के निजी हिस्से दिखाने की ज़रूरत नहीं है.", "2. Haritt क्या नहीं करेगा", "वह यह **नहीं** कहेगा कि फ्लैट पर staff, खुलने का समय, या दुकान या showroom है. वह इसे branch, head office या registered office नहीं कहेगा. वह हमेशा लिखेगा कि मीटिंग **सिर्फ़ appointment पर** होती है.", "वह फ्लैट पर staff, माल, सामान या फ़ाइलें **नहीं** रखेगा. कोई बोर्ड या साइन नहीं लगाएगा. बिना बताए आने वाले visitors, कार्यक्रम, बिक्री या नकद लेन-देन नहीं होगा.", "वह इस पते को GST, Udyam, कंपनी registration, या बैंक या payment account के फ़ॉर्म में **इस्तेमाल नहीं करेगा**. अगर आगे इसकी ज़रूरत पड़ी तो मालिक को अलग से लिखकर हाँ कहना होगा.", "वह मालिक का नाम, फोटो या निजी जानकारी वेबसाइट पर या कहीं भी सार्वजनिक रूप से नहीं डालेगा. वह फ्लैट के अंदर की फोटो अपलोड नहीं करेगा.", "Haritt अपनी listing के लिए Google के नियम मानेगा. अगर Google listing को रोक दे या हटा दे, तो यह सिर्फ़ Haritt की समस्या है. अगर listing से परेशानी हो (जैसे लोग बिना appointment आएँ, या सोसाइटी शिकायत करे), तो मालिक **15 दिन के नोटिस** पर Haritt से उसे हटाने को कह सकता है और Haritt 7 दिन में हटा देगा. बाकी इजाज़तें चलती रहेंगी.", "Haritt Group की दूसरी ventures इस पते का इस्तेमाल तब तक नहीं करेंगी जब तक मालिक लिखकर हाँ न कहे (9.2 देखें).", "3. फ्लैट पर मीटिंग", "Haritt WhatsApp या ईमेल से पहले से पूछेगा, **कम से कम 2 दिन पहले**. वह तारीख, समय, मकसद और आने वाले लोगों के नाम बताएगा.", "मालिक 1 दिन में जवाब देगा. मालिक सिर्फ़ ठीक कारण से मना कर सकता है, जैसे: वह खाली नहीं है, परिवार या सेहत का कारण, मरम्मत का काम, सोसाइटी का नियम, सुरक्षा, या पहले से न बताया गया visitor. वह कारण बताएगा और 7 दिन के अंदर दूसरा दिन देगा.", "सीमाएँ: महीने में अधिकतम **4 मीटिंग** (मालिक के लिखित संदेश से बढ़ाई जा सकती हैं), हर मीटिंग अधिकतम **2 घंटे**, **सुबह 10 से शाम 6 बजे** के बीच, अधिकतम **4 लोग**.", "Haritt के ग्राहक और business partners आ सकते हैं, लेकिन सिर्फ़ तब जब उनके नाम पहले से बताए गए हों, और उनके साथ एक founder ज़रूर आए. Haritt अपने visitors के व्यवहार के लिए ज़िम्मेदार है और सोसाइटी के नियम मानेगा.", "4. चिट्ठियाँ और courier", "मालिक घर पर होने पर Haritt की चिट्ठियाँ और पार्सल सुरक्षित रखेगा. वह cash-on-delivery, कीमती, भारी या संदिग्ध सामान लेने से मना कर सकता है.", "अगर सरकारी, टैक्स, बैंक या कोर्ट की चिट्ठी आए, तो मालिक **2 कामकाजी दिन के अंदर** Haritt को बताएगा और उसे खोलेगा नहीं. Haritt उसे 7 दिन में ले जाएगा.", "अगर कोई चिट्ठी खो जाए तो मालिक ज़िम्मेदार नहीं है, जब तक उसने बहुत लापरवाही न की हो. वह कानूनी नोटिस लेने के लिए Haritt का agent नहीं है.", "courier और वापसी का सारा खर्च Haritt देगा.", "5. यह एग्रीमेंट क्या नहीं है", "यह **किराए का एग्रीमेंट, lease या tenancy नहीं है**. Haritt को फ्लैट के किसी भी हिस्से में **रहने, कब्ज़ा रखने या मालिक बनने का कोई हक़ नहीं** मिलता. मालिक का पूरा नियंत्रण रहता है और वह फ्लैट बेच या किराए पर दे सकता है.", "इससे मालिक Haritt का partner, employer या guarantor नहीं बन जाता. Haritt के बिज़नेस, कर्ज़, टैक्स या contracts के लिए मालिक **ज़िम्मेदार नहीं** है.", "किसी भी तरफ़ से **कोई पैसा नहीं** देना है. Haritt अपना खर्च खुद उठाएगा. मालिक फ्लैट का सोसाइटी, टैक्स और बिजली का बिल हमेशा की तरह भरेगा. अगर कभी पैसे की बात तय हो, तो वह लिखी हुई और दोनों के साइन वाली होनी चाहिए.", "6. ज़िम्मेदारी", "Haritt अपने बिज़नेस, अपनी डाक की सामग्री और अपने visitors के लिए ज़िम्मेदार है. अगर Haritt या उसके visitors फ्लैट में कुछ नुकसान करें, तो Haritt उसकी भरपाई करेगा. अगर Haritt के बिज़नेस या इस पते की वजह से कोई मालिक पर दावा करे, तो Haritt उसे संभालेगा और खर्च उठाएगा, जब तक वह मालिक की अपनी गलती से न हुआ हो.", "मालिक वादा करता है कि: वह फ्लैट का मालिक है (या सभी मालिक सहमत हैं); कोई बैंक, मकान मालिक या builder का नियम इसे नहीं रोकता; और उसने जाँच लिया है कि उसकी सोसाइटी इस पते पर चिट्ठियाँ लेने, कभी-कभी ग्राहक मीटिंग और Google listing को मना नहीं करती. अगर यह सच नहीं निकला और Haritt को अपने रिकॉर्ड बदलने पड़े, तो मालिक उसका वाजिब खर्च ₹{{cap}} तक देगा.", "अगर मालिक की सोसाइटी, कोई नियम, नोटिस, बिक्री, गिरवी (mortgage) या फ्लैट छोड़ने की योजना इस एग्रीमेंट पर असर डाल सकती है, तो मालिक **7 दिन के अंदर** Haritt को बताएगा. अगर कोई नियम या आदेश किसी एक बात को मना कर दे, तो सिर्फ़ वही बात रुकेगी. बाकी चलता रहेगा.", "7. निजता", "दोनों पक्ष एक-दूसरे की निजी जानकारी निजी रखेंगे. Haritt मालिक के ID की कॉपी सुरक्षित रखेगा, उन्हें सिर्फ़ इसी एग्रीमेंट के लिए इस्तेमाल करेगा, और एग्रीमेंट खत्म होने के 30 दिन के अंदर मिटा देगा. मालिक Haritt की डाक नहीं खोलेगा, जब तक सुरक्षा या कानून के लिए ज़रूरी न हो.", "8. कितने समय चलेगा और कैसे खत्म होगा", "यह ऊपर की तारीख से शुरू होता है और **12 महीने** चलता है. फिर हर साल अपने आप चलता रहता है, जब तक कोई 30 दिन का नोटिस देकर आगे न चलाने को न कहे.", "पहले 12 महीनों में **Haritt** कभी भी **15 दिन के नोटिस** पर इसे खत्म कर सकता है. **मालिक** इसे सिर्फ़ इन कारणों से खत्म कर सकता है: Haritt एग्रीमेंट तोड़े और 7 दिन में ठीक न करे; सोसाइटी या कानून का कोई नियम इसे असंभव बना दे; फ्लैट बिक जाए या उसे छोड़ना पड़े; Haritt अपना बिज़नेस बंद कर दे; या मालिक की मृत्यु हो जाए या वह काम करने में असमर्थ हो (तब उसका परिवार 30 दिन के नोटिस पर इसे खत्म कर सकता है).", "12 महीने के बाद कोई भी पक्ष किसी भी कारण से **30 दिन के लिखित नोटिस** पर इसे खत्म कर सकता है. WhatsApp या ईमेल चलेगा.", "नोटिस के दौरान सब कुछ तय के अनुसार चलता रहेगा. पहले से तय हो चुकी मीटिंग रहेंगी, सिवाय आपातकाल के.", "नोटिस के समय के अंदर Haritt पते को अपनी वेबसाइट, **Google listing**, profiles और कागज़ात से हटा देगा, और मालिक को लिखकर बताएगा. मालिक **खत्म होने की तारीख के 60 दिन बाद तक** चिट्ठियाँ लेता रहेगा, उसके बाद उन्हें भेजने वाले को लौटा सकता है.", "अगर मालिक माँगे, या Haritt माँगे, तो मालिक एक छोटा पत्र देगा जिसमें लिखा होगा कि इस अवधि में Haritt ने पते का इस्तेमाल उसकी इजाज़त से किया.", "9. साफ़ रिकॉर्ड रखना", "सिर्फ़ यह एग्रीमेंट और बाद के लिखित संदेश (नीचे दिए नंबरों से WhatsApp या ईमेल) इजाज़त माने जाएँगे. ज़ुबानी वादे नहीं गिने जाएँगे.", "इस एग्रीमेंट में जो लिखा है उसे कोई भी पक्ष बाद में मना नहीं कर सकता. कोई भी नई इजाज़त लिखित होनी चाहिए, जैसे: “हाँ, आप यह इस तारीख को कर सकते हैं.”", "संदेश के लिए संपर्क. मालिक: {{owner_mobile}}, {{owner_email}}. Haritt: developers@haritt.com, {{haritt_mobile}}.", "10. समस्याएँ", "अगर कोई मतभेद हो, तो पहले 7 दिन में बात करें और 15 दिन में सुलझाने की कोशिश करें. न सुलझे तो किसी निष्पक्ष मध्यस्थ (mediator) की मदद लें. फिर भी न सुलझे तो जयपुर, राजस्थान की अदालतें तय करेंगी. भारतीय कानून लागू होगा.", "11. अन्य बातें", "Haritt रजिस्टर्ड नहीं है, इसलिए **founders भी अपने नाम से साइन करते हैं** और यहाँ Haritt के वादों के लिए खुद ज़िम्मेदार हैं. अगर Haritt आगे रजिस्टर होता है, तो वह 15 दिन में मालिक को बताएगा और दोनों एक छोटे नोट पर साइन करेंगे जिससे यह एग्रीमेंट रजिस्टर्ड बिज़नेस को दिया जाएगा.", "कोई भी पक्ष यह एग्रीमेंट किसी और को नहीं दे सकता. बदलाव लिखित और दोनों के साइन वाले होने चाहिए, सिवाय 9.2 के तहत नई इजाज़तों के.", "इस विषय पर यही पूरा एग्रीमेंट है. दोनों पक्षों ने इसे पढ़ा और समझा है, और अपनी मर्ज़ी से साइन करते हैं. स्टाम्प पेपर का खर्च Haritt देगा."], "vars": [{"k": "cap", "l": "Amount Owner pays for damage cap (Rs.)", "def": "5000"}, {"k": "haritt_mobile", "l": "Haritt mobile", "def": "8952042717"}], "roles": [{"id": "f1", "label": "Founder, Haritt Developers", "labelHi": "Founder, Haritt Developers", "note": "for Haritt Developers and personally", "fields": []}, {"id": "f2", "label": "Founder, Haritt Developers", "labelHi": "Founder, Haritt Developers", "note": "for Haritt Developers and personally", "fields": []}, {"id": "owner", "label": "Flat owner", "labelHi": "फ्लैट मालिक", "note": "", "fields": [{"k": "parent", "l": "Father / mother / husband name", "lh": "पिता / माता / पति का नाम", "h": "e.g. S/o Ramesh Sharma", "hh": "जैसे S/o रमेश शर्मा", "ph": "S/o ..."}, {"k": "addr", "l": "Your home address", "lh": "आपके घर का पता", "multi": 1}, {"k": "mobile", "l": "Your mobile number", "lh": "आपका मोबाइल नंबर", "tel": 1}, {"k": "flat_addr", "l": "Flat address to be used", "lh": "इस्तेमाल होने वाला फ्लैट का पता", "h": "Flat no., building, area, PIN", "hh": "फ्लैट नं., बिल्डिंग, एरिया, PIN", "multi": 1}, {"k": "place", "l": "City where you sign", "lh": "आप कहाँ साइन कर रहे हैं (शहर)", "def": "Jaipur"}]}]}, {"id": "client", "name": "Client service agreement", "title": "Client Service Agreement", "subtitle": "Haritt Developers · a Haritt Group company", "md": "## Parties\n- **Haritt Developers**, a venture of **Haritt Group**. It is a business that is not yet registered. Its working address is Behind Shiva Talkies, Sahyog Nagar, Bharatpur, Rajasthan 321001. Email: developers@haritt.com. It signs through **{{haritt_name}}**. (“Haritt”)\n- **Client:** **{{client_name}}**, {{client_company}}, address {{client_addr}}. Email: {{client_email}}. Mobile: {{client_phone}}. (“Client”)\n## The project\nProject: **{{project_name}}**. Haritt will provide the services below for the Client.\n# What Haritt will do\n- {{scope}}\n- Haritt will first understand the Client's business, then recommend a plan, do the work, and support it after delivery.\n- Haritt will share progress and ask for approval at the main stages.\n- Haritt will use outside services (for example hosting, payment or marketing platforms) only where the project needs them, and will tell the Client before any paid service is used.\n# Time\n- Work starts after the advance payment is received. Planned time: **{{timeline}}**. Dates depend on the Client giving content, feedback and approvals on time.\n# Fees and payment\n- Total fee: **Rs. {{fee}}**.\n- **{{advance}}** is paid in advance before work starts. The rest is paid like this: {{payment_terms}}.\n- Each invoice is due within **7 days**. Payment is by UPI or bank transfer as written on the invoice.\n- Outside costs (domain, hosting, ads, platform fees) are paid by the Client unless this agreement says Haritt pays them.\n# What the Client will do\n- Give the content, access, details and approvals Haritt needs, on time.\n- Make sure the material the Client gives is lawful and the Client has the right to use it.\n- Pay on time. Work can pause if a payment is late.\n# Changes\n- Work outside the scope above is a change. Haritt will tell the Client the extra cost and time first, and will start only after the Client agrees in writing (WhatsApp or email is fine).\n# Ownership\n- After full payment, the Client owns the final work made for this project. Haritt keeps its own tools, templates and general know-how and can use them for other clients.\n- Until full payment is received, Haritt keeps ownership of the work.\n- Haritt may show the project in its portfolio only after the Client agrees.\n# Honest results\n- Haritt will do its work with care. Haritt does not promise sales, rankings, followers or any particular business result, because these also depend on things outside its control.\n# Privacy\n- Both sides will keep each other's business information private and use it only for this project.\n# Ending this agreement\n- Either side can end it with **7 days' written notice** (WhatsApp or email is fine). The Client pays for work done and costs paid until then. Advance for work not yet started is returned.\n# Problems\n- If there is a disagreement, both sides first talk for 7 days. If it is not solved, the courts at Bharatpur, Rajasthan will decide. Indian law applies.\n# Other points\n- This is the full agreement for this project. Any change must be written and agreed by both sides.", "hi": null, "vars": [{"k": "project_name", "l": "Project name"}, {"k": "scope", "l": "What Haritt will deliver (scope)", "multi": 1}, {"k": "timeline", "l": "Planned time", "def": "to be agreed in writing"}, {"k": "fee", "l": "Total fee (Rs.)"}, {"k": "advance", "l": "Advance", "def": "25% of the total fee"}, {"k": "payment_terms", "l": "Payment of the rest", "def": "balance on delivery"}], "roles": [{"id": "haritt", "label": "Haritt Developers", "labelHi": "", "note": "authorised signatory", "fields": []}, {"id": "client", "label": "Client", "labelHi": "", "note": "", "fields": [{"k": "company", "l": "Company or business name", "opt": 1}, {"k": "addr", "l": "Business address", "multi": 1}]}]}, {"id": "blank", "name": "Blank agreement", "title": "Agreement", "subtitle": "", "md": "## Parties\n- {{party1_name}}\n# First point\n- Write the first point here.\n# Signing\n- Both sides agree to the points above.", "hi": null, "vars": [], "roles": [{"id": "party1", "label": "Haritt Developers", "labelHi": "", "note": "", "fields": []}, {"id": "party2", "label": "Other party", "labelHi": "", "note": "", "fields": []}]}];
function mdOf(items){return items.map(it=>it.k==="h"?(/^\d+\.\s/.test(it.t)?"# "+it.t.replace(/^\d+\.\s+/,""):"## "+it.t):it.k==="cl"?"- "+it.t:it.t).join("\n")}
function parseMd(md){const out=[];let sec=0,idx=0,ins=false;
  for(let raw of String(md||"").split("\n")){const l=raw.trim();if(!l)continue;let m;
    if(m=l.match(/^##\s+(.*)$/))out.push({k:"h",t:m[1]});
    else if(m=l.match(/^#\s+(.*)$/)){sec++;idx=0;ins=true;out.push({k:"h",t:sec+". "+m[1]})}
    else if(m=l.match(/^-\s+(.*)$/)){idx++;out.push({k:"cl",n:ins?sec+"."+idx:idx+".",t:m[1]})}
    else out.push({k:"p",t:l})}
  return out}
const normMd=s=>String(s||"").split("\n").map(x=>x.trim()).filter(Boolean).join("\n");
const TOKRE=/\{\{(\w+)\}\}/g;
let SESS="",ADM={docs:[],tpls:[],drafts:[]},ME={admin:true,email:"",perms:{view:1,create:1,send:1,delete:1}};const setAdm=l=>{ADM=l;if(l.me)ME=l.me};const can=p=>!ME||!!(ME.perms&&ME.perms[p]);
