  doc.setFont("helvetica","normal");doc.setFontSize(8.5);doc.setTextColor(...MUT);const sl=doc.splitTextToSize(DOC.subtitle||"",CW);if(DOC.subtitle){doc.text(sl,W/2,y,{align:"center"});y+=sl.length*4+3}else y+=1;
